    descriptionAdvanced: {
      de: "Akan-Mashū-Nationalpark ist ein bemerkenswertes Element der japanischen Geografie und Kultur. Ein Nationalpark in Hokkaidō mit Vulkanen, Wäldern und drei spektakulären Seen: Akan, Mashū und Kussharo. Der Mashū-See ist einer der klarsten Seen der Welt. Bekannt für Marimo, seltene Algenkugeln im Akan-See. Dieses Naturgebiet zeigt die landschaftliche Vielfalt Japans, vom Fuji-Vulkan über die Inlandsee bis zu den Pazifikküsten und vulkanischen Inselbögen. Wie viele bedeutende Orte in Japan verbindet dieser Ort regionale Eigenheiten mit dem Erbe der Samurai-Tradition, des Shintoismus und Buddhismus sowie der modernen Industrienation. Damit trägt dieser Ort zum vielseitigen Profil Japans bei — vom Fuji-Vulkan über Tokio bis zum vulkanischen Inselbogen am Pazifik.",
      hu: "A(z) Akan-Mashū Nemzeti Park a japán földrajz és kultúra figyelemre méltó eleme. Egy nemzeti park Hokkaidóban, vulkánokkal, erdőkkel és három látványos tóval: Akan, Mashū és Kussharo. A Mashū-tó a világ egyik legtisztább tava. Az Akan-tóban található ritka marimo algagolyókról ismert. Ez a természeti terület Japán tájainak sokszínűségét mutatja, a Fudzsi-hegytől a Beltengeren át a Csendes-óceán partjáig és a vulkáni szigetívekig. Japán számos jelentős helyszínéhez hasonlóan ez is ötvözi a regionális sajátosságokat a szamuráj-hagyomány, a sintoizmus és a buddhizmus, valamint a modern ipari nemzet örökségével. Ezzel a helyszín hozzájárul Japán sokszínű arculatához — a Fudzsi-hegytől Tokión át a Csendes-óceán vulkáni szigetívéig.",
      ro: "Parcul Național Akan-Mashū este un element remarcabil al geografiei și culturii japoneze. Un parc național în Hokkaidō care prezintă vulcani, păduri și trei lacuri spectaculoase: Akan, Mashū și Kussharo. Lacul Mashū este unul dintre cele mai limpezi lacuri din lume. Renumit pentru Marimo, bile rare de alge găsite în Lacul Akan. Această zonă naturală reflectă diversitatea peisajului japonez, de la vulcanul Fuji și Marea Interioară până la coastele Pacificului și arcurile insulare vulcanice. Asemenea multor locuri importante din Japonia, acesta îmbină particularitățile regionale cu moștenirea tradiției samurailor, a șintoismului și budismului, precum și a națiunii industriale moderne. Astfel, acest loc contribuie la profilul variat al Japoniei — de la vulcanul Fuji, prin Tokyo, până la arcul insular vulcanic din Pacific.",
      en: "Akan-Mashū National Park is a remarkable feature of the geography and culture of Japan. A national park in Hokkaidō featuring volcanoes, forests, and three spectacular lakes: Akan, Mashū, and Kussharo. Lake Mashū is one of the clearest lakes in the world. Known for marimo, rare algae balls found in Lake Akan. This natural area reflects the scenic diversity of Japan, from Mount Fuji and the Inland Sea to the Pacific coasts and volcanic island arcs. Like many notable places in Japan, it combines regional character with the legacy of the samurai tradition, Shinto and Buddhist heritage, and the modern industrial nation. Thus, this place contributes to the diverse profile of Japan — from Mount Fuji and Tokyo to the volcanic island arc along the Pacific.",
      es: "El Parque Nacional Akan-Mashū es una pieza fundamental de la geografía volcánica de Japón. Situado en el este de Hokkaidō, el parque es célebre por sus calderas espectaculares y la pureza de sus aguas; el lago Mashū es considerado uno de los más transparentes del mundo. Es también el hogar del Marimo, una rara alga esférica protegida que habita en el lago Akan. Este entorno natural ilustra la diversidad paisajística nipona, desde los picos volcánicos hasta las costas del Pacífico. Como muchos lugares sagrados en Japón, la zona entrelaza la herencia natural con las tradiciones espirituales y el respeto por el medio ambiente, contribuyendo al perfil único de un país definido por su actividad geológica y su profunda conexión con la tierra, desde el Fuji hasta los arcos insulares.",
      pt: "O Parque Nacional Akan-Mashu é um elemento notável da geografia e cultura japonesa. Um parque nacional em Hokkaido com vulcões, florestas e três lagos espetaculares: Akan, Mashu e Kussharo. O Lago Mashu é um dos lagos mais claros do mundo. É conhecido pelo Marimo, bolas de algas raras no Lago Akan. Esta área natural mostra a diversidade paisagística do Japão, do vulcão Fuji através do Mar Interior até às costas do Pacífico e arcos de ilhas vulcânicas. Como muitos lugares importantes no Japão, este local combina peculiaridades regionais com a herança da tradição Samurai, do Xintoísmo e Budismo, bem como da nação industrial moderna. Assim, este lugar contribui para o perfil multifacetado do Japão — do vulcão Fuji através de Tóquio até o arco de ilhas vulcânicas no Pacífico.",
      fr: "Le parc national d'Akan-Mashū est un élément remarquable de la géographie et de la culture japonaises. Situé à Hokkaido, il abrite des volcans, des forêts et trois lacs spectaculaires : Akan, Mashū et Kussharo. Le lac Mashū est l'un des lacs les plus limpides au monde. Le site est réputé pour le Marimo, une algue sphérique rare que l'on trouve dans le lac Akan. Cet espace naturel illustre la diversité des paysages japonais, du mont Fuji à la mer intérieure de Seto en passant par les côtes du Pacifique. Comme beaucoup de sites majeurs, ce lieu allie les spécificités locales à l'héritage samouraï, shintoïste et bouddhiste, ainsi qu'à la nation industrielle moderne. Il participe ainsi au profil varié du Japon, entre volcans et métropoles.",
    },
